UPDATE `#__guidedtours` SET `autostart` = 0;
INSERT INTO `#__guidedtours` (`title`, `uid`, `description`, `ordering`, `extensions`, `url`, `created`, `created_by`, `modified`, `modified_by`, `published`, `language`, `note`, `access`, `autostart`) VALUES ('Verrouiller un article', 'joomlaguide-locking-an-article-fr', '<p>Quand quelqu\'un modifie un article, Joomla le <em>verrouille</em> : personne d\'autre ne peut le modifier en même temps. Enregistrer ou fermer l\'article le <em>déverrouille</em> à nouveau.</p><p>Si la personne quitte l\'article sans l\'enregistrer ni le fermer, il reste verrouillé. Dans cette visite, vous voyez comment cela arrive et comment un administrateur le déverrouille.</p><p>Cette visite suit le tutoriel <a href="https://guide.joomla.org/fr/tutoriels/gestion-des-contenus/7-publication-et-acces/7-5-verrouiller-un-article" target="_blank" rel="noopener">7.5 Verrouiller un article</a> du Guide de l\'utilisateur de Joomla.</p>', 1, '["com_cpanel","com_content"]', 'administrator/index.php', CURRENT_TIMESTAMP(), 0, CURRENT_TIMESTAMP(), 0, 1, '*', 'Joomla User Guide: 7.5 Locking an Article', 1, 1);
INSERT INTO `#__guidedtour_steps` (`tour_id`, `title`, `description`, `ordering`, `position`, `target`, `type`, `interactive_type`, `url`, `created`, `created_by`, `modified`, `modified_by`, `published`, `language`, `note`, `params`) VALUES
((SELECT `id` FROM `#__guidedtours` WHERE `uid` = 'joomlaguide-locking-an-article-fr'), 'Contenus', '<p>Dans le menu à gauche, cliquez sur <strong>Contenus</strong>.</p><p>Il s\'ouvre et montre ce que vous pouvez y faire.</p>', 1, 'right', 'body.com_cpanel #sidebarmenu li.item-level-1:has(a[href="index.php?option=com_content&view=articles"]) > a.has-arrow', 2, 4, 'administrator/index.php', CURRENT_TIMESTAMP(), 0, CURRENT_TIMESTAMP(), 0, 1, '*', '', NULL),
((SELECT `id` FROM `#__guidedtours` WHERE `uid` = 'joomlaguide-locking-an-article-fr'), 'Contenus › Articles', '<p>Cliquez sur <strong>Articles</strong>, dans <strong>Contenus</strong>.</p>', 2, 'right', 'body.com_cpanel #sidebarmenu a[href="index.php?option=com_content&view=articles"]', 2, 1, 'administrator/index.php', CURRENT_TIMESTAMP(), 0, CURRENT_TIMESTAMP(), 0, 1, '*', '', NULL),
((SELECT `id` FROM `#__guidedtours` WHERE `uid` = 'joomlaguide-locking-an-article-fr'), 'Ouvrir l\'article', '<p>Cliquez sur <strong>Le conseil municipal approuve le nouveau budget de transport</strong> pour le modifier.</p>', 3, 'right', '#articleList tr:has(a[href*="task=article.edit"][title$=" Le conseil municipal approuve le nouveau budget de transport"]) a[href*="task=article.edit"]', 2, 1, 'administrator/index.php?option=com_content&view=articles', CURRENT_TIMESTAMP(), 0, CURRENT_TIMESTAMP(), 0, 1, '*', '', NULL),
((SELECT `id` FROM `#__guidedtours` WHERE `uid` = 'joomlaguide-locking-an-article-fr'), 'Partir sans fermer', '<p>Vous modifiez maintenant l\'article. Ne cliquez ni sur <strong>Enregistrer</strong> ni sur <strong>Fermer</strong> : appuyez sur le bouton <em>Précédent</em> de votre navigateur. C\'est ce que fait un rédacteur qui part sans fermer.</p><p>De retour dans la liste, l\'article a un cadenas : il est verrouillé. Survolez le cadenas pour voir qui l\'a verrouillé, et quand. (Pas de cadenas ? Rechargez la page.)</p>', 4, 'right', '#articleList tr:has(a[href*="task=article.edit"][title$=" Le conseil municipal approuve le nouveau budget de transport"]) th', 0, 1, 'administrator/index.php?option=com_content&view=articles', CURRENT_TIMESTAMP(), 0, CURRENT_TIMESTAMP(), 0, 1, '*', '', NULL),
((SELECT `id` FROM `#__guidedtours` WHERE `uid` = 'joomlaguide-locking-an-article-fr'), 'Qui peut le modifier ?', '<p>C\'est vous qui avez verrouillé l\'article : vous pouvez donc encore l\'ouvrir. Les autres utilisateurs, même administrateurs, obtiennent un message d\'erreur s\'ils essaient.</p><p>Quand vous cliquez sur <strong>Fermer</strong> ou <strong>Enregistrer & Fermer</strong> dans l\'article, il est à nouveau déverrouillé.</p>', 5, 'bottom', '#articleList tr:has(a[href*="task=article.edit"][title$=" Le conseil municipal approuve le nouveau budget de transport"])', 0, 1, 'administrator/index.php?option=com_content&view=articles', CURRENT_TIMESTAMP(), 0, CURRENT_TIMESTAMP(), 0, 1, '*', '', NULL),
((SELECT `id` FROM `#__guidedtours` WHERE `uid` = 'joomlaguide-locking-an-article-fr'), 'Déverrouiller l\'article', '<p>Ici, le rédacteur n\'est pas revenu. En tant qu\'administrateur, vous pouvez déverrouiller l\'article : cliquez sur le cadenas.</p>', 6, 'right', '#articleList tr:has(a[href*="task=article.edit"][title$=" Le conseil municipal approuve le nouveau budget de transport"]) [data-item-task="articles.checkin"]', 2, 1, 'administrator/index.php?option=com_content&view=articles', CURRENT_TIMESTAMP(), 0, CURRENT_TIMESTAMP(), 0, 1, '*', '', NULL),
((SELECT `id` FROM `#__guidedtours` WHERE `uid` = 'joomlaguide-locking-an-article-fr'), 'Bravo !', '<p>L\'article est déverrouillé, et toute personne autorisée peut à nouveau le modifier.</p><p>Pour déverrouiller plusieurs articles d\'un coup, cochez leurs cases et choisissez <strong>Actions</strong> › <strong>Déverrouillage</strong>.</p><p>Attention : si le rédacteur travaille encore sur l\'article, ses modifications risquent d\'être perdues.</p>', 7, 'bottom', '#system-message-container', 0, 1, 'administrator/index.php?option=com_content&view=articles', CURRENT_TIMESTAMP(), 0, CURRENT_TIMESTAMP(), 0, 1, '*', '', NULL);
